var UNITS = [{"n": 1, "title": "Art. 516 (efeitos 2025): CGSN, receita bruta, vedações e princípios", "cvar": "u1", "lessons": [{"id": "K1", "type": "teoria", "title": "Governança do Simples, art. 3º, art. 12 e art. 17", "xp": 10, "data": "V1"}, {"id": "K2", "type": "drill", "title": "Praticar · CGSN e vedações", "xp": 25, "data": ["S1", "S2", "S3", "S4", "T0", "T1", "T2", "T3", "T4"]}, {"id": "K3", "type": "flash", "title": "Flashcards · CGSN e vedações", "xp": 15, "data": [0, 1, 2, 3, 4, 5, 6, 7, 8]}]}, {"n": 2, "title": "Declarações, guarda de documentos e multas (arts. 25, 25-B, 26, 38 e 38-A)", "cvar": "u2", "lessons": [{"id": "K4", "type": "teoria", "title": "Declaração do MEI, declaração assistida, escrituração e multas", "xp": 10, "data": "V2"}, {"id": "K5", "type": "drill", "title": "Praticar · obrigações acessórias", "xp": 25, "data": ["S5", "S6", "S7", "S8", "S9", "T5", "T6", "T7", "T8", "T9"]}, {"id": "K6", "type": "flash", "title": "Flashcards · declarações e multas", "xp": 15, "data": [9, 10, 11, 12, 13, 14, 15, 16, 17]}]}, {"n": 3, "title": "Art. 517 (efeitos 2027): sublimite, IBS e CBS no Simples, créditos", "cvar": "u3", "lessons": [{"id": "K7", "type": "teoria", "title": "Limites, opção pelo regime regular, alíquota efetiva, split e créditos", "xp": 10, "data": "V3"}, {"id": "K8", "type": "drill", "title": "Praticar · art. 517", "xp": 25, "data": ["S10", "S11", "S12", "S13", "S14", "T10", "T11", "T12", "T13", "T14"]}, {"id": "K9", "type": "flash", "title": "Flashcards · art. 517 (2027)", "xp": 15, "data": [18, 19, 20, 21, 22, 23, 24, 25, 26]}]}, {"n": 4, "title": "Art. 518 (2033) e a mecânica dos Anexos XVIII a XXII", "cvar": "u4", "lessons": [{"id": "K10", "type": "teoria", "title": "Só IBS em 2033, alíquota efetiva e parcela a deduzir", "xp": 10, "data": "V4"}, {"id": "K11", "type": "drill", "title": "Praticar · art. 518 e anexos", "xp": 25, "data": ["S15", "S16", "S17", "S18", "S19", "T15", "T16", "T17", "T18"]}, {"id": "K12", "type": "flash", "title": "Flashcards · art. 518 e anexos", "xp": 15, "data": [27, 28, 29, 30, 31, 32]}]}, {"n": 5, "title": "Partilha do Simples por anexo e por ano (2027 a 2033)", "cvar": "u5", "lessons": [{"id": "K13", "type": "teoria", "title": "Colunas, redução de ICMS/ISS, teto do ISS e repartição da 5ª faixa", "xp": 10, "data": "V5"}, {"id": "K14", "type": "drill", "title": "Praticar · partilha", "xp": 25, "data": ["S20", "S21", "S22", "S23", "S24", "S25", "T19", "T20", "T21", "T22", "T23"]}, {"id": "K15", "type": "flash", "title": "Flashcards · partilha", "xp": 15, "data": [33, 34, 35, 36, 37, 38, 39, 40]}]}, {"n": 6, "title": "MEI: art. 18-A e Anexo XXIII (Anexo VII da LC 123)", "cvar": "u1", "lessons": [{"id": "K16", "type": "teoria", "title": "Valores fixos do MEI de 2027 a 2033 e obrigações", "xp": 10, "data": "V6"}, {"id": "K17", "type": "drill", "title": "Praticar · MEI", "xp": 25, "data": ["S26", "S27", "S28", "S29", "S30", "T24", "T25", "T26", "T27", "T28"]}, {"id": "K18", "type": "flash", "title": "Flashcards · MEI", "xp": 15, "data": [41, 42, 43, 44, 45, 46]}]}, {"n": 7, "title": "Fixação", "cvar": "u1", "lessons": [{"id": "Krev", "type": "review", "title": "Revisão geral do módulo", "xp": 60, "data": null}, {"id": "K19", "type": "missao", "title": "Missão TEC Concursos", "xp": 15, "data": null}, {"id": "K20", "type": "prova", "title": "Simulado cronometrado", "xp": 100, "data": null}]}];
var COM = {"0": "<p>Certo. Art. 544, II.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "1": "<p>Certo. Art. 2º, I, da LC 123, na redação do art. 516.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "2": "<p>Errado. São designados pelo Ministro de Estado da Fazenda, mediante indicação (art. 2º, § 8º).</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "3": "<p>Certo. Art. 3º, § 4º, XII.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "4": "<p>Errado. O art. 3º, § 1º, as exclui.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "5": "<p>Certo. Art. 25-B, parágrafo único.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "6": "<p>Certo. Art. 25, § 8º.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "7": "<p>Errado. Incide “ainda que integralmente pago”.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "8": "<p>Certo. Art. 38-A, §§ 5º e 6º.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "9": "<p>Errado. O limite é de 20%.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "10": "<p>Certo. Art. 13, IX, X e §§ 9º e 10.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "11": "<p>Errado. O art. 13, § 1º, XIV-A, o coloca entre os tributos que não integram o recolhimento unificado.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "12": "<p>Certo. Art. 87-B.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "13": "<p>Errado. Art. 21, § 14-A: só se a operação não gerou crédito e observado o art. 166 do CTN.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "14": "<p>Certo. Art. 23, § 1º-A.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "15": "<p>Certo. Art. 518.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "16": "<p>Certo. Cálculo: nos limites das faixas a efetiva coincide.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "17": "<p>Errado. Mudam apenas na 6ª faixa a partir de 2029 (18,90% para 19,00%).</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "18": "<p>Certo. Art. 18-A, § 4º-B.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "19": "<p>Certo. ICMS cai 10/20/30/40% e a diferença vai ao IBS.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "20": "<p>Errado. O teto cai: 4,5% (2029), 4% (2030), 3,5% (2031) e 3% (2032).</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "21": "<p>Certo. A tabela de 2033 do Anexo XIX traz IRPJ, CSLL, CBS, CPP, IPI e IBS.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "22": "<p>Certo. Tabelas do Anexo XX: 2027-28 e a partir de 2029.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "23": "<p>Certo. Soma: 31,33 + 32,00 + 36,27 + 0,40 = 100.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "24": "<p>Certo. Anexo XXIII (2033): CBS R$ 1,00 e IBS R$ 2,00.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "25": "<p>Certo. ICMS 1,00; ISS 5,00; CBS 0,994; IBS 0,006.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "26": "<p>Errado. Art. 26, § 6º, II: a emissão é obrigatória.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "27": "<p>Certo. Anexo XXIII, ano-calendário 2029.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "28": "<p>Certo. Art. 18-A, § 3º, V.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>"};
